(() => {
  const channel = 'nodedance-elfinder-grid';
  let state, finder, applying = false, selected = [];
  const emit = (type, value) => parent.postMessage({ channel, type, ...value }, location.origin);
  const hash = path => 'r_' + btoa(String.fromCharCode(...new TextEncoder().encode(path))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
  const parentPath = path => path.substring(0, path.lastIndexOf('/')) || '/';
  const paths = hashes => (Array.isArray(hashes) ? hashes : hashes ? [hashes] : finder.selected()).map(value => finder.file(value)?.ndpath).filter(Boolean);
  const mime = name => { const extension = name.toLowerCase().split('.').pop(); const types={png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',webp:'image/webp',bmp:'image/bmp',pdf:'application/pdf',zip:'application/zip',gz:'application/x-gzip',tar:'application/x-tar',bz2:'application/x-bzip2',mp3:'audio/mpeg',mp4:'video/mp4',webm:'video/webm',txt:'text/plain',md:'text/plain',json:'application/json',js:'application/javascript',html:'text/plain',svg:'text/plain'}; return Object.hasOwn(types,extension)?types[extension]:'application/octet-stream'; };
  const file = row => ({hash:hash(row.path),phash:row.path==='/'?undefined:hash(parentPath(row.path)),name:row.name,mime:row.kind==='directory'?'directory':mime(row.name),size:row.size,ts:Math.floor(Number(row.modifiedAt)/1e9),read:1,write:1,dirs:row.kind==='directory'?1:0,ndpath:row.path,volumeid:'r_'});
  const snapshot = () => {
    const ancestors=[];for(let path=state.path;;path=parentPath(path)){ancestors.push(file({path,name:path==='/'?'/':path.split('/').pop(),kind:'directory',size:0,modifiedAt:0}));if(path==='/')break}
    return {api:'2.1',cwd:ancestors[0],files:[...ancestors,...state.rows.map(file)],options:{path:state.path,separator:'/',disabled:[],copyOverwrite:false,uploadOverwrite:false,archivers:{create:['application/zip'],extract:['application/zip','application/x-tar','application/x-gzip','application/x-bzip2']},syncMinMs:0,url:'',tmbUrl:''},uplMaxSize:'0'};
  };
  const select = () => { if(!finder)return; applying=true;finder.trigger('selectfiles',{files:selected.map(hash)});applying=false; };
  const initialize = () => {
    applying=true;if(finder){finder.destroy();finder=null}document.getElementById('grid').replaceChildren();
    const commands=['open','quicklook','edit','download','info','copy','cut','paste','rename','rm','archive','extract','reload','selectall'];
    finder=new elFinder(document.getElementById('grid'),{url:'/',baseUrl:'/vendor/elfinder/',cssAutoLoad:false,themes:{nodedance:'themes/nodedance/manifest.json'},theme:'nodedance',lang:state.language==='zh-CN'?'zh_CN':'en',ui:[],commands,defaultView:'icons',rememberLastDir:false,useBrowserHistory:false,resizable:false,height:innerHeight,width:'100%',enableAlways:false,allowShortcuts:true,dragUploadAllow:'none',sortType:'nodedance',sortOrder:'asc',sortStickFolders:false,sortRules:{nodedance:(a,b)=>state.rows.findIndex(row=>row.path===a.ndpath)-state.rows.findIndex(row=>row.path===b.ndpath)},contextmenu:{navbar:[],cwd:['paste','reload'],files:['open','quicklook','edit','download','|','copy','cut','paste','rename','rm','|','archive','extract','info']},transport:{send:options=>{const pending=jQuery.Deferred();pending.abort=()=>pending.reject({status:0,statusText:"abort"});queueMicrotask(()=>options.data.cmd==='open'?pending.resolve(snapshot()):options.data.cmd==='ls'?pending.resolve({list:{}}):pending.reject(['errUnknownCmd']));return pending}},handlers:{select:event=>{if(!applying)emit('selection',{paths:paths(event.data.selected)})},dblclick:event=>{event.preventDefault();emit('action',{action:'open',paths:paths(event.data.file?[event.data.file]:undefined)})},load:()=>{finder.changeTheme('nodedance');applying=false;select();if(state.busy)finder.disable();emit('ready',{})}}});
    for(const name of commands){const command=finder.getCommand(name);if(!command||name==='selectall')continue;if(name==='paste')command.getstate=()=>state.canPaste||finder.clipboard().length?0:-1;command.exec=targets=>{const values=paths(targets);if(name==='copy'||name==='cut')finder.clipboard(Array.isArray(targets)?targets:finder.selected(),name==='cut');if(name==='paste'){const clipboard=finder.clipboard();emit('action',{action:'paste',paths:clipboard.map(item=>finder.file(item.hash)?.ndpath).filter(Boolean),destination:values[0]||state.path,cut:clipboard[0]?.cut===true})}else emit('action',{action:name,paths:values});return jQuery.Deferred().resolve()}}
  };
  addEventListener('message',event=>{if(event.source!==parent||event.origin!==location.origin||event.data?.channel!==channel)return;const message=event.data;if(message.type==='data'){state=message.value;initialize()}else if(message.type==='selection'){selected=message.paths;select()}else if(message.type==='status'&&state){state.busy=message.busy;state.canPaste=message.canPaste;if(finder){message.busy?finder.disable():finder.enable();finder.getCommand('paste')?.update()}}});
  addEventListener('resize',()=>finder?.resize(innerWidth,innerHeight));
  addEventListener('keydown',event=>{if(event.key==='Escape')emit('escape',{})});
  emit('mounted',{});
})();
